# 大文件分片清单(每个脚本都携带完整清单, 保证任意执行顺序都能触发合并)
$manifest = @(
    'src\assets\404_images\404.png|2'
    'src\assets\custom-theme\index.css|8'
    'src\assets\images\chart-map.png|6'
    'src\assets\images\detection-bg.png|11'
    'src\assets\images\header-11.png|2'
    'src\assets\images\header-preview.png|2'
)

# 第一步: 还原本部分携带的完整文件(先创建目录结构, 再解码 Base64 写入二进制内容)
$count = 0
foreach ($rel in $map.Keys) {
    $dest = Join-Path $TargetRoot $rel
    $destDir = Split-Path $dest -Parent
    if (!(Test-Path $destDir)) { New-Item -ItemType Directory -Path $destDir -Force | Out-Null }
    [IO.File]::WriteAllBytes($dest, [Convert]::FromBase64String($map[$rel]))
    $count++
}

# 第二步: 写出本部分携带的分片片段(以文本形式存为 <目标文件>.part<序号> 临时文件)
foreach ($k in $chunks.Keys) {
    $bar = $k.LastIndexOf("|")
    $rel = $k.Substring(0, $bar)
    $idx = $k.Substring($bar + 1)
    $dest = Join-Path $TargetRoot ($rel + ".part" + $idx)
    $destDir = Split-Path $dest -Parent
    if (!(Test-Path $destDir)) { New-Item -ItemType Directory -Path $destDir -Force | Out-Null }
    [IO.File]::WriteAllText($dest, $chunks[$k])
    $count++
}

# 第三步: 检测分片是否到齐, 到齐则拼接解码还原大文件并清理临时分片(顺序无关, 幂等可重复执行)
$merged = 0
foreach ($m in $manifest) {
    $bar = $m.IndexOf("|")
    $rel = $m.Substring(0, $bar)
    $total = [int]$m.Substring($bar + 1)
    $dest = Join-Path $TargetRoot $rel
    $ready = $true
    for ($i = 0; $i -lt $total; $i++) {
        if (!(Test-Path ($dest + ".part$i"))) { $ready = $false; break }
    }
    if ($ready) {
        $b64 = ""
        for ($i = 0; $i -lt $total; $i++) { $b64 += [IO.File]::ReadAllText($dest + ".part$i") }
        [IO.File]::WriteAllBytes($dest, [Convert]::FromBase64String($b64))
        for ($i = 0; $i -lt $total; $i++) { Remove-Item ($dest + ".part$i") -Force }
        $merged++
    }
}
Write-Host ("还原完成(第 21/32 部分): 写入 $count 项, 合并大文件 $merged 个, 目标目录: $TargetRoot")
